import os
import boto3
from botocore.exceptions import ClientError

def normalize_expense(payload, config=None):
    config = config or {}
    client = boto3.client(
        'textract',
        aws_access_key_id=config.get('aws_access_key_id', os.environ.get('AWS_ACCESS_KEY_ID')),
        aws_secret_access_key=config.get('aws_secret_access_key', os.environ.get('AWS_SECRET_ACCESS_KEY')),
        region_name=config.get('region_name', os.environ.get('AWS_REGION', 'us-east-1'))
    )
    try:
        if isinstance(payload, str) and os.path.isfile(payload):
            with open(payload, 'rb') as document:
                image_bytes = document.read()
        else:
            image_bytes = payload
        response = client.analyze_expense(Document={'Bytes': image_bytes})
        normalized = {
            'vendor_name': None,
            'invoice_date': None,
            'total_amount': None,
            'tax_amount': None,
            'line_items': []
        }
        for expense_doc in response.get('ExpenseDocuments', []):
            for summary_field in expense_doc.get('SummaryFields', []):
                label = summary_field.get('LabelDetection', {}).get('Text', '').lower()
                value_text = summary_field.get('ValueDetection', {}).get('Text')
                if 'vendor' in label:
                    normalized['vendor_name'] = value_text
                elif 'date' in label:
                    normalized['invoice_date'] = value_text
                elif 'total' in label and 'tax' not in label:
                    normalized['total_amount'] = value_text
                elif 'tax' in label:
                    normalized['tax_amount'] = value_text
            for line_item_group in expense_doc.get('LineItemGroups', []):
                for line_item in line_item_group.get('LineItems', []):
                    line_item_data = {}
                    for field in line_item.get('LineItemExpenseFields', []):
                        field_label = field.get('LabelDetection', {}).get('Text', '').lower()
                        field_value = field.get('ValueDetection', {}).get('Text')
                        if 'description' in field_label:
                            line_item_data['description'] = field_value
                        elif 'quantity' in field_label:
                            line_item_data['quantity'] = field_value
                        elif 'unit price' in field_label or 'price' in field_label:
                            line_item_data['unit_price'] = field_value
                        elif 'amount' in field_label:
                            line_item_data['amount'] = field_value
                    if line_item_data:
                        normalized['line_items'].append(line_item_data)
        result = normalized
    except ClientError as e:
        result = {'error': str(e)}
    return result
